# ========================
# INPUT
# ========================

S_hex = """"""

n_hex = """"""

e = 65537

# ========================
# PROCESS
# ========================

S = int(S_hex, 16)
n = int(n_hex, 16)

EM = pow(S, e, n)

EM_bytes = EM.to_bytes((EM.bit_length() + 7) // 8, 'big')

# ========================
# OUTPUT 
# ========================

print("=== EM' (hex) ===")
print(EM_bytes.hex())

print("\n=== Kiểm tra cấu trúc PKCS#1 ===")
print("Byte đầu:", EM_bytes[0])
print("Byte thứ 2:", EM_bytes[1])

# tìm vị trí 00 (kết thúc padding)
sep_index = EM_bytes.find(b'\x00', 2)

print("Vị trí kết thúc padding:", sep_index)

padding = EM_bytes[2:sep_index]
data = EM_bytes[sep_index+1:]

print("\n=== Padding ===")
print(padding.hex())

print("\n=== Dữ liệu sau padding (ASN.1 + hash) ===")
print(data.hex())